<h1>{{ config('ideyra.name') }} application received</h1><p>{{ $application->reference }} · {{ ucfirst($application->type) }}</p><p>Applicant: {{ $application->payload['applicant_name'] }}</p><p>Institution: {{ $application->payload['institution_name'] }}</p><p>Location: {{ $application->country }}, {{ $application->payload['city'] }}</p><p>Submitted: {{ $application->created_at->toIso8601String() }}</p><p>Capabilities of interest: {{ implode(', ', $application->payload['features'] ?? []) }}</p><p>Challenges: {{ \Illuminate\Support\Str::limit($application->payload['project_challenges'] ?? '', 500) }}</p><p>{{ $application->type === 'student' ? 'A student recommendation; no institutional agreement or account has been created.' : 'An institutional application awaiting review; no institution or account has been created.' }}</p><p><a href="{{ rtrim(config('app.url'), '/').route('system.applications.show', $application, false) }}">Secure administrative review (System Administrator login required)</a></p>
